// intent: Exercises write_cbor_key and write_msgpack_key with a key type that is implicitly convertible to string_t.
#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct convertible_key {
    std::string s;
    bool operator<(const convertible_key& o) const { return s < o.s; }
    operator std::string() const { return s; }
};

namespace nlohmann {
template <typename T>
struct adl_serializer;

template <>
struct adl_serializer<convertible_key> {
    static void to_json(nlohmann::json& j, const convertible_key& k) { j = k.s; }
};
}

template <class Key, class Value>
tusing conv_map = std::map<Key, Value, std::less<Key>>;
using conv_json = nlohmann::basic_json<conv_map>;

int main() {
    conv_json j;
    j.emplace(convertible_key{"test_key"}, conv_json(123));
    auto cbor = conv_json::to_cbor(j);
    auto msgpack = conv_json::to_msgpack(j);
    std::cout << "CBOR size: " << cbor.size() << ", MsgPack size: " << msgpack.size() << std::endl;
    return 0;
}
